struct Vec3 { float x, y, z; };

Vec3 CalcAngle(const Vec3& src, const Vec3& dst) {
    Vec3 d{ dst.x - src.x, dst.y - src.y, dst.z - src.z };
    float hyp = sqrtf(d.x*d.x + d.y*d.y);
    return { atan2f(-d.z, hyp) * 180.f / 3.14159265f,   // pitch
             atan2f(d.y, d.x) * 180.f / 3.14159265f }; // yaw
}

Vec3 Smooth(const Vec3& cur, const Vec3& target, float factor /*0.2~0.4 拟人*/) {
    Vec3 o;
    o.x = cur.x + (target.x - cur.x) * factor;
    o.y = cur.y + (target.y - cur.y) * factor;
    return o;
}
