// aim_base.cpp — x64, MSVC / clang-cl
// cl /std:c++17 /O2 aim_base.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <cmath>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static uint64_t ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uint64_t base = 0;
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { base = (uint64_t)me.modBaseAddr; break; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

int main() {
    const wchar_t* PROC = L"[进程名]";      // 例：L"GameClient.exe"
    const wchar_t* MOD  = L"[模块名]";      // 例：L"GameClient.exe"
    DWORD pid = FindPid(PROC);
    if (!pid) { printf("process not found\n"); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("OpenProcess failed %lu\n", GetLastError()); return 1; }

    uint64_t base = ModuleBase(pid, MOD);
    printf("pid=%lu base=0x%llX\n", pid, (unsigned long long)base);

    auto rd = [&](uint64_t addr, void* buf, size_t sz) -> bool {
        SIZE_T got = 0;
        return ReadProcessMemory(h, (LPCVOID)addr, buf, sz, &got) && got == sz;
    };

    // 多级指针链：base + [偏移0] -> [偏移1] -> ... -> UWorld
    struct Chain { uint64_t off; };
    const uint64_t WORLD_CHAIN[] = { 0x0[偏移0], 0x0[偏移1] }; // 待 dynamic 角色实测填入
    uint64_t world = base;
    for (auto off : WORLD_CHAIN) {
        uint64_t nxt = 0;
        if (!rd(world + off, &nxt, 8)) { printf("chain break @0x%llX\n", (unsigned long long)(world+off)); return 1; }
        world = nxt;
    }
    printf("UWorld=0x%llX\n", (unsigned long long)world);

    CloseHandle(h);
    return 0;
}
