## 2. 最小读写驱动（WDM，`[进程名]` 走 IOCTL 传入 PID）

`DrvReadWrite.c` 核心：

```c
#include <ntifs.h>

#define IOCTL_READ  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQ {
    ULONG  Pid;
    ULONG64 Address;
    ULONG64 Buffer;
    ULONG  Size;
    ULONG  Result;
} RW_REQ, *PRW_REQ;

NTSTATUS DoRead(PRW_REQ r) {
    PEPROCESS ep = NULL;
    if (!NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)r->Pid, &ep))) return STATUS_NOT_FOUND;
    KAPC_STATE apc;
    KeStackAttachProcess(ep, &apc);
    __try {
        ProbeForRead((PVOID)r->Address, r->Size, 1);
        RtlCopyMemory((PVOID)r->Buffer, (PVOID)r->Address, r->Size);
        r->Result = r->Size;
    } __except (EXCEPTION_EXECUTE_HANDLER) { r->Result = 0; }
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(ep);
    return STATUS_SUCCESS;
}
// DoWrite 同理，方向反过来（MmCopyVirtualMemory 版本可换，绕 CR3 检查更稳）
```

`DriverEntry` 里 `IoCreateDevice` / `IoCreateSymbolicLink` + `IRP_MJ_DEVICE_CONTROL` 分发到 DoRead/DoWrite 即可。**加载命令**（管理员）：

