## 1. 驱动骨架：`MmCopyVirtualMemory` 读写

不挂 `ObRegisterCallbacks`、不做进程保护——EAC 的句柄扫描对自定义回调很敏感，读写走内核直接调 `PsLookupProcessByProcessId` + `MmCopyVirtualMemory`，用户态只开一个 IOCTL 通道，句柄权限降到 `PROCESS_QUERY_LIMITED_INFORMATION` 即可。

`EacRw.h`：
```c
#pragma once
#include <ntifs.h>

#define EACRW_DEVICE_NAME    L"\\Device\\EacRw"
#define EACRW_SYMLINK_NAME   L"\\DosDevices\\EacRw"

#define IOCTL_EACRW_READ  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_EACRW_WRITE CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_EACRW_BASE  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQUEST {
    ULONG  Pid;
    ULONG64 Address;
    PVOID  Buffer;
    SIZE_T Size;
    ULONG64 ModuleBase;   // BASE 请求回填
    ULONG   ModuleSize;
} RW_REQUEST, *PRW_REQUEST;
```

`EacRw.c` 核心：
```c
#include "EacRw.h"

static PDEVICE_OBJECT g_Device = NULL;

static NTSTATUS DoReadWrite(PRW_REQUEST req, BOOLEAN bWrite)
{
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    SIZE_T done = 0;
    if (bWrite) {
        st = MmCopyVirtualMemory(PsGetCurrentProcess(), req->Buffer,
                                 proc, (PVOID)req->Address,
                                 req->Size, KernelMode, &done);
    } else {
        st = MmCopyVirtualMemory(proc, (PVOID)req->Address,
                                 PsGetCurrentProcess(), req->Buffer,
                                 req->Size, KernelMode, &done);
    }
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG len = sp->Parameters.DeviceIoControl.OutputBufferLength;

    PRW_REQUEST req = (PRW_REQUEST)irp->AssociatedIrp.SystemBuffer;
    if (req && len >= sizeof(RW_REQUEST)) {
        switch (sp->Parameters.DeviceIoControl.IoControlCode) {
        case IOCTL_EACRW_READ:  st = DoReadWrite(req, FALSE); break;
        case IOCTL_EACRW_WRITE: st = DoReadWrite(req, TRUE);  break;
        case IOCTL_EACRW_BASE: {
            PEPROCESS proc = NULL;
            st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc);
            if (NT_SUCCESS(st)) {
                // 用 PsGetProcessSectionBaseAddress 拿主模块基址
                req->ModuleBase = (ULONG64)PsGetProcessSectionBaseAddress(proc);
                ObDereferenceObject(proc);
                st = STATUS_SUCCESS;
            }
            break;
        }
        default: break;
        }
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = NT_SUCCESS(st) ? len : 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

