#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { DWORD p = pe.th32ProcessID; CloseHandle(snap); return p; }
    CloseHandle(snap); return 0;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, mod)) { uintptr_t b = (uintptr_t)me.modBaseAddr; CloseHandle(snap); return b; }
    CloseHandle(snap); return 0;
}

class Mem {
    HANDLE h = nullptr;
public:
    bool Attach(DWORD pid) {
        h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
        return h != nullptr;
    }
    template<class T> bool Rd(uintptr_t addr, T& out) {
        SIZE_T n = 0;
        return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), &n) && n == sizeof(T);
    }
    template<class T> bool Wr(uintptr_t addr, const T& v) {
        SIZE_T n = 0;
        return WriteProcessMemory(h, (LPVOID)addr, &v, sizeof(T), &n) && n == sizeof(T);
    }
    // 多级指针链: base 是模块基址, offsets 由外到内
    uintptr_t Chain(uintptr_t base, const uint32_t* offs, int n) {
        uintptr_t cur = base;
        for (int i = 0; i < n; ++i) {
            uintptr_t next = 0;
            if (!Rd(cur + offs[i], next)) return 0;
            cur = next;
        }
        return cur;
    }
};
