```cpp
// be_probe.cpp — 探测 BattlEye 是否剥离句柄权限
#include <windows.h>
#include <cstdio>

int main(int argc, char** argv) {
    if (argc < 2) { printf("usage: be_probe.exe <pid>\n"); return 1; }
    DWORD pid = (DWORD)atoi(argv[1]);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) {
        printf("[!] OpenProcess failed, GetLastError=%lu (BE 剥句柄或进程已退出)\n", GetLastError());
        return 2;
    }

    // 再查实际拿到的权限，BE 的 ObRegisterCallbacks 会把 VM_READ 摘掉
    DWORD got = 0;
    if (GetHandleInformation(h, &got))
        printf("[+] OpenProcess OK, handle flags=0x%lx\n", got);
    else
        printf("[!] GetHandleInformation failed=%lu\n", GetLastError());

    BYTE buf[16] = {0};
    SIZE_T rd = 0;
    // 读目标模块头部，验证 VM_READ 是否真的可用
    if (ReadProcessMemory(h, (LPCVOID)0x140000000, buf, sizeof(buf), &rd))
        printf("[+] ReadProcessMemory OK, %zu bytes, magic=%02X%02X\n", rd, buf[0], buf[1]);
    else
        printf("[!] ReadProcessMemory failed=%lu (句柄已剥权限)\n", GetLastError());

    CloseHandle(h);
    return 0;
}
```

