## 一、驱动工程（KMDF/WDM 均可，下面是 WDM 风格最小实现）

`drv/DrvMain.c`：

```c
#include <ntifs.h>
#include <ntddk.h>

#define DEV_NAME    L"\\Device\\NachoRW"
#define SYM_NAME    L"\\DosDevices\\NachoRW"

// 通信协议
typedef struct _RW_REQ {
    ULONG  Pid;         // 目标 PID
    PVOID  Addr;        // 目标地址
    PVOID  Buffer;      // 用户态缓冲
    ULONG  Size;
    ULONG  Op;          // 1=读 2=写
} RW_REQ, *PRW_REQ;

static HANDLE g_PidHandleMap[64] = {0}; // 简化：不缓存，直接按 pid 打开
UNICODE_STRING g_SymLink;

NTSTATUS DoRead(PRW_REQ req) {
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    SIZE_T done = 0;
    st = MmCopyVirtualMemory(proc, req->Addr, PsGetCurrentProcess(),
                             req->Buffer, req->Size, KernelMode, &done);
    ObDereferenceObject(proc);
    return st;
}

NTSTATUS DoWrite(PRW_REQ req) {
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    SIZE_T done = 0;
    st = MmCopyVirtualMemory(PsGetCurrentProcess(), req->Buffer,
                             proc, req->Addr, req->Size, KernelMode, &done);
    ObDereferenceObject(proc);
    return st;
}

NTSTATUS DispatchCreate(PDEVICE_OBJECT dev, PIRP irp) {
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

NTSTATUS DispatchClose(PDEVICE_OBJECT dev, PIRP irp) {
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    ULONG code = sp->Parameters.DeviceIoControl.IoControlCode;
    ULONG inLen = sp->Parameters.DeviceIoControl.InputBufferLength;
    NTSTATUS st = STATUS_INVALID_PARAMETER;

    if (code == 0x222000 && inLen >= sizeof(RW_REQ)) {
        PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;
        __try {
            st = (req->Op == 1) ? DoRead(req) : DoWrite(req);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
            st = GetExceptionCode();
        }
    }

    irp->IoStatus.Status = st;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING regPath) {
    PDEVICE_OBJECT dev = NULL;
    UNICODE_STRING devName;
    RtlInitUnicodeString(&devName, DEV_NAME);
    RtlInitUnicodeString(&g_SymLink, SYM_NAME);

    NTSTATUS st = IoCreateDevice(drv, 0, &devName, FILE_DEVICE_UNKNOWN,
                                 FILE_DEVICE_SECURE_OPEN, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;

    st = IoCreateSymbolicLink(&g_SymLink, &devName);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }

    drv->MajorFunction[IRP_MJ_CREATE] = DispatchCreate;
