## 二、第一段：OpenProcess + 剥权限降级探测（验证 ACE 有没有 `ObRegisterCallbacks`）

```cpp
// probe_ace.cpp  —— 先确认 ACE 拦到什么权限
#include <windows.h>
#include <stdio.h>

int main(int argc, char** argv) {
    const wchar_t* proc = (argc > 1) ? L"目标进程" : L"[进程名]"; // 占位符
    DWORD pid = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) do {
        if (_wcsicmp(pe.szExeFile, proc) == 0) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    if (!pid) { printf("[-] 进程未找到: %ws\n", proc); return 1; }

    // 逐级降权，看 ACE 的 ObRegisterCallbacks 拦到哪一档
    struct { DWORD access; const char* name; } tests[] = {
        { PROCESS_ALL_ACCESS,               "PROCESS_ALL_ACCESS" },
        { PROCESS_VM_READ|PROCESS_VM_WRITE|PROCESS_VM_OPERATION, "VM_RW_OP" },
        { PROCESS_VM_READ,                  "VM_READ only" },
        { PROCESS_QUERY_INFORMATION,        "QUERY_INFORMATION" },
    };
    for (auto& t : tests) {
        HANDLE h = OpenProcess(t.access, FALSE, pid);
        if (h) { printf("[+] %-20s OK  handle=0x%p\n", t.name, h); CloseHandle(h); }
        else   { printf("[-] %-20s DENIED err=%lu\n", t.name, GetLastError()); }
    }
    return 0;
}
```

