// hit 是 "48 8B 05 disp" 的起始
int32_t disp = *(int32_t*)(hit + 3);
uint64_t gObjects = (uint64_t)hit + 7 + disp;   // 这是「保存 GObjects 的全局变量地址」
// 或者：
uint64_t gObjectsPtr = *(uint64_t*)(gObjects);  // 实际 FUObjectArray*
```

