## 2. 手工物理地址翻译

```c
#include <ntifs.h>
#include <intrin.h>

#define PAGE_OFFSET_MASK  0x0FFFULL
#define PML4_INDEX(va)    (((va) >> 39) & 0x1FF)
#define PDPT_INDEX(va)    (((va) >> 30) & 0x1FF)
#define PD_INDEX(va)      (((va) >> 21) & 0x1FF)
#define PT_INDEX(va)      (((va) >> 12) & 0x1FF)
#define PTE_PRESENT(x)    ((x) & 1)
#define PTE_LARGE(x)      ((x) & (1ULL << 7))
#define PTE_PFN(x)        ((x) & 0x000FFFFFFFFFF000ULL)

/* 物理地址 -> 内核虚拟地址（用 MmMapIoSpaceEx 一次性 map 一个页）
 * 注意：不要用 MmGetVirtualForPhysical 对任意 PA，它只对 RAM 且需 MDL 语义 */
static PVOID PhysToVirt(PHYSICAL_ADDRESS pa) {
    return MmMapIoSpaceEx(pa, PAGE_SIZE, PAGE_READWRITE | PAGE_NOCACHE);
}
static void VirtUnmap(PVOID va) {
    MmUnmapIoSpace(va, PAGE_SIZE);
}

/* 核心：用自己的方式读一个页表项里指向的下一级表
 * 遍历时全程在目标进程 CR3 下进行，避免切回 System 进程导致换页 */
static PTE_ENTRY *WalkTable(UINT64 tablePhys, UINT64 index) {
    PHYSICAL_ADDRESS pa = { .QuadPart = tablePhys };
    PTE_ENTRY *va = (PTE_ENTRY *)PhysToVirt(pa);
    if (!va) return NULL;
    PTE_ENTRY *slot = &va[index];
    return slot; // 调用方负责用完 VirtUnmap（这里用固定表页就不频繁 unmap）
}

/* 把目标进程 CR3 下的 VA 翻译成 PA。
 * 失败返回 0；large page (2MB/1GB) 也处理。 */
UINT64 TranslateVaToPa(UINT64 cr3, UINT64 va) {
    UINT64 pml4Phys = cr3 & 0x000FFFFFFFFFF000ULL;

    PTE_ENTRY *pml4 = WalkTable(pml4Phys, PML4_INDEX(va));
    if (!pml4 || !PTE_PRESENT(*pml4)) return 0;

    PTE_ENTRY *pdpt = WalkTable(PTE_PFN(*pml4), PDPT_INDEX(va));
    if (!pdpt || !PTE_PRESENT(*pdpt)) return 0;
    if (PTE_LARGE(*pdpt)) { // 1GB page
        return PTE_PFN(*pdpt) + (va & ((1ULL << 30) - 1));
    }

    PTE_ENTRY *pd = WalkTable(PTE_PFN(*pdpt), PD_INDEX(va));
    if (!pd || !PTE_PRESENT(*pd)) return 0;
    if (PTE_LARGE(*pd)) { // 2MB page
        return PTE_PFN(*pd) + (va & ((1ULL << 21) - 1));
    }

    PTE_ENTRY *pt = WalkTable(PTE_PFN(*pd), PT_INDEX(va));
    if (!pt || !PTE_PRESENT(*pt)) return 0;
    return PTE_PFN(*pt) + (va & PAGE_OFFSET_MASK);
}
```

> 注意 `WalkTable` 里每次 `MmMapIoSpaceEx` 都占一个映射槽，遍历结束要 `VirtUnmap`。生产版应缓存上一级物理页的映射，这里为了骨架可读性每次映射一次，**性能不敏感可以接受**；高频读写建议改成先翻译完整条路径，重复使用相同 PML4/PDPT/PD 映射。

