## 一、物理链路与打开参数

| 型号 | 上位机接口 | 默认参数 |
| --- | --- | --- |
| kmbox B / B+ | USB 转串口（CH340/CP210x），Windows 下 `COMx` | `115200 8N1`，无流控 |
| kmbox Net | 以太网，UDP | `本机任意端口 → 盒子 IP:8888` |
| kmbox Pro | USB CDC + 串口 | `115200 8N1` |

Windows 打开（Win32，不依赖第三方库）：

```cpp
#include <windows.h>

HANDLE OpenKmBox(const wchar_t* port, DWORD baud = 115200) {
    HANDLE h = CreateFileW(port, GENERIC_READ | GENERIC_WRITE, 0, nullptr,
                           OPEN_EXISTING, 0, nullptr);
    if (h == INVALID_HANDLE_VALUE) return nullptr;

    DCB dcb{};
    dcb.DCBlength = sizeof(dcb);
    GetCommState(h, &dcb);
    dcb.BaudRate = baud;
    dcb.ByteSize = 8;
    dcb.Parity   = NOPARITY;
    dcb.StopBits = ONESTOPBIT;
    dcb.fBinary  = TRUE;
    dcb.fParity  = FALSE;
    dcb.fOutxCtsFlow = FALSE;
    dcb.fOutxDsrFlow = FALSE;
    dcb.fDtrControl  = DTR_CONTROL_DISABLE;
    dcb.fRtsControl  = RTS_CONTROL_DISABLE;
    dcb.fOutX = dcb.fInX = FALSE;
    SetCommState(h, &dcb);

    COMMTIMEOUTS to{};
    to.ReadIntervalTimeout        = MAXDWORD;
    to.ReadTotalTimeoutConstant   = 50;
    to.ReadTotalTimeoutMultiplier = 0;
    to.WriteTotalTimeoutConstant  = 50;
    to.WriteTotalTimeoutMultiplier= 0;
    SetCommTimeouts(h, &to);

    PurgeComm(h, PURGE_RXCLEAR | PURGE_TXCLEAR);
    return h;
}
```

