// g++ rw.cpp -o rw.exe -lpsapi
#include <windows.h>
#include <psapi.h>
#include <tlhelp32.h>
#include <cstdio>

static DWORD FindPid(const wchar_t* name) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    for (BOOL ok = Process32FirstW(h, &pe); ok; ok = Process32NextW(h, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    CloseHandle(h);
    return pid;
}

static ULONG_PTR ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE s = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    ULONG_PTR base = 0;
    for (BOOL ok = Module32FirstW(s, &me); ok; ok = Module32NextW(s, &me))
        if (!_wcsicmp(me.szModule, mod)) { base = (ULONG_PTR)me.modBaseAddr; break; }
    CloseHandle(s);
    return base;
}

