## Windows x64：进程/模块基址 + 多级偏移读写骨架

```cpp
// x64 Release, /MT
#include <windows.h>
#include <TlHelp32.h>
#include <vector>
#include <cstdio>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static ULONGLONG ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32W me{ sizeof(me) };
    ULONGLONG base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, mod) == 0) { base = (ULONGLONG)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

// 指针链解析: base + [off0] -> +off1 -> +off2 ...
template <typename T>
static bool ResolveChain(HANDLE h, ULONGLONG base, const std::vector<ULONGLONG>& chain, T& out) {
    ULONGLONG addr = base;
    for (size_t i = 0; i + 1 < chain.size(); ++i) {
        ULONGLONG p = 0;
        if (!ReadProcessMemory(h, (LPCVOID)(addr + chain[i]), &p, 8, nullptr) || !p) return false;
        addr = p;
    }
    return ReadProcessMemory(h, (LPCVOID)(addr + chain.back()), &out, sizeof(T), nullptr) != 0;
}

int wmain() {
    const wchar_t* PROC = L"[进程名].exe";
    const wchar_t* MOD  = L"[模块名].exe";

    DWORD pid = FindPid(PROC);
    if (!pid) { wprintf(L"pid not found\n"); return 1; }
    ULONGLONG base = ModuleBase(pid, MOD);
    wprintf(L"pid=%lu base=0x%llX\n", pid, base);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed %lu\n", GetLastError()); return 1; }

    // 示例：base + [0x01A2B3C0] + 0x10 + 0x28 -> int32
    std::vector<ULONGLONG> chain = { 0x01A2B3C0, 0x10, 0x28 };
    int32_t val = 0;
    if (ResolveChain(h, base, chain, val)) {
        wprintf(L"value = %d\n", val);
        int32_t nv = 999;
        ULONGLONG addr = base;
        for (size_t i = 0; i + 1 < chain.size(); ++i) {
            ULONGLONG p = 0;
            ReadProcessMemory(h, (LPCVOID)(addr + chain[i]), &p, 8, nullptr);
            addr = p;
        }
        WriteProcessMemory(h, (LPCVOID)(addr + chain.back()), &nv, sizeof(nv), nullptr);
    } else {
        wprintf(L"chain unresolved: 0x%llX 未验证\n", base);
    }
    CloseHandle(h);
    return 0;
}
```

偏移占位符（`0x01A2B3C0 / 0x10 / 0x28`）全部标 **未验证**，必须用 CE / x64dbg 实际扫出来替换。

## 找偏移的标准动作（执行顺序）

1. **CE 定位数值**：搜 int32 已知值 → 改值过滤 → 得到动态地址。
2. **找基址**：右键「找出是什么访问了这个地址」→ 记录指令里 `[reg+disp]` → 回溯 `reg` 来源，逐级得到 `模块+偏移 → +off → +off`。
3. **模块基址**：CE 里 `[模块名].exe+偏移`，确认重启进程后基址随 `modBaseAddr` 变化而偏移不变。
4. **验证**：改值后界面数字必须同步变化，否则链条错。

