    uintptr_t base = GetModuleBase(pid, L"[模块名].exe");
    wprintf(L"pid=%lu base=0x%llX\n", pid, base);

    // 多级指针链：base + [偏移1] -> +[偏移2] -> 目标值
    uintptr_t p1 = 0, p2 = 0;
    ReadProcessMemory(h, (LPCVOID)(base + [偏移1]), &p1, sizeof(p1), nullptr);
    ReadProcessMemory(h, (LPCVOID)(p1 + [偏移2]), &p2, sizeof(p2), nullptr);

    int value = 0;
    ReadProcessMemory(h, (LPCVOID)(p2 + [偏移3]), &value, sizeof(value), nullptr);
    wprintf(L"current value = %d\n", value);

    // 写前先 dump 原值，可回滚
    int newValue = [目标值];
    WriteProcessMemory(h, (LPVOID)(p2 + [偏移3]), &newValue, sizeof(newValue), nullptr);
    wprintf(L"written %d (old was %d, revert: write %d back)\n", newValue, value, value);

    CloseHandle(h);
    return 0;
}
